/// Look up a class id by simple ecore name (binary search).
pub fn name_to_id(name: &str) -> Option<u32> {
    NAME_TO_ID
        .binary_search_by(|(n, _)| n.cmp(&name))
        .ok()
        .map(|i| NAME_TO_ID[i].1)
}

/// Look up a class id by arxml element name (`xml.name`).
pub fn xml_name_to_id(xml: &str) -> Option<u32> {
    XML_NAME_TO_ID
        .binary_search_by(|(n, _)| n.cmp(&xml))
        .ok()
        .map(|i| XML_NAME_TO_ID[i].1)
}

/// Look up an enum id by name.
pub fn enum_id(name: &str) -> Option<u32> {
    ENUM_NAME_TO_ID
        .binary_search_by(|(n, _)| n.cmp(&name))
        .ok()
        .map(|i| ENUM_NAME_TO_ID[i].1)
}

/// Enum metadata by id.
pub fn enum_meta(id: u32) -> EnumMeta {
    ENUMS[id as usize]
}

/// Data type metadata by id.
pub fn datatype_meta(id: u32) -> DataTypeMeta {
    DATATYPES[id as usize]
}
